import React from 'react';
import { motion } from 'framer-motion';

const WhyMe = () => {
  const points = [
    {
      emoji: "🧠",
      title: "Component-Driven Development",
      text: "Architecting scalable solutions with clean, reusable code and modular thinking",
    },
    {
      emoji: "🚀",
      title: "Performance Obsession",
      text: "Optimized experiences with lightning-fast load times and buttery animations",
    },
    {
      emoji: "📚",
      title: "Continuous Growth",
      text: "Dedicated to mastering new technologies through deliberate practice",
    },
    {
      emoji: "🛠️",
      title: "Full-Stack Mindset",
      text: "End-to-end ownership from pixel-perfect UI to robust backend systems",
    },
  ];

  // Animation variants
  const container = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const item = {
    hidden: { opacity: 0, y: 20 },
    show: { opacity: 1, y: 0, transition: { duration: 0.6 } }
  };

  return (
    <section className="relative py-20 px-6 md:px-12 lg:px-24 bg-gradient-to-br from-[#f8fafc] to-[#f1f5f9] overflow-hidden">
      {/* Decorative elements */}
      <div className="absolute top-0 left-0 w-full h-full opacity-5">
        <div className="absolute top-20 left-10 w-32 h-32 rounded-full bg-blue-500 mix-blend-multiply filter blur-xl"></div>
        <div className="absolute bottom-10 right-10 w-40 h-40 rounded-full bg-indigo-500 mix-blend-multiply filter blur-xl"></div>
      </div>
      
      <div className="relative max-w-7xl mx-auto">
        <motion.div 
          className="text-center mb-16"
          initial={{ opacity: 0, y: -20 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          viewport={{ once: true, margin: "-100px" }}
        >
          <span className="inline-block mb-4 text-sm font-semibold tracking-wider text-indigo-600 uppercase">
            Competitive Edge
          </span>
          <motion.h2 
            className="text-4xl md:text-5xl font-bold text-gray-900 mb-4"
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            transition={{ delay: 0.2 }}
          >
            Why Choose Me?
          </motion.h2>
          <motion.p 
            className="max-w-2xl mx-auto text-xl text-gray-600"
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            transition={{ delay: 0.4 }}
          >
            A unique blend of technical expertise and creative problem-solving
          </motion.p>
        </motion.div>

        <motion.div 
          className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8"
          variants={container}
          initial="hidden"
          whileInView="show"
          viewport={{ once: true, margin: "-100px" }}
        >
          {points.map((point, index) => (
            <motion.div
              key={index}
              className="bg-white rounded-xl shadow-lg hover:shadow-xl transition-all duration-300 overflow-hidden border border-gray-100"
              variants={item}
              whileHover={{ y: -8 }}
            >
              <div className="p-8 text-center">
                <div className="w-20 h-20 mx-auto mb-6 rounded-2xl bg-indigo-50 flex items-center justify-center text-3xl">
                  {point.emoji}
                </div>
                <h3 className="text-xl font-bold text-gray-900 mb-3">{point.title}</h3>
                <p className="text-gray-600 leading-relaxed">{point.text}</p>
              </div>
            </motion.div>
          ))}
        </motion.div>

        
      </div>
    </section>
  );
};

export default WhyMe;