import { motion } from 'framer-motion';
import aboutImage from '../assets/images/about.jpg';
import { FaCode, FaServer, FaMobileAlt, FaChartLine } from 'react-icons/fa';
import ReactExpertise from '../components/about/ReactExpertise';
import MyJourney from '../components/about/MyJourney';
import WhyMe from '../components/about/WhyMe';
import Connect from '../components/about/Connect';




const About = () => {
  const experiences = [
    {
      role: "WEB DEVELOPER",
      company: "QUANTUMSTACK",
      period: "Aug 2023 - Present",
      points: [
        "Optimized database solutions and UI/UX, reducing page load time by 36%",
        "Implemented robust deployment strategies ensuring smooth website performance",
        "Developed Task Management Apps with React and Indexes",
        "Built Personal Finance Tracker using React and Node.js"
      ],
      icon: <FaCode className="text-xl" />
    },
    {
      role: "WEB DEVELOPER",
      company: "%2 DEVIS",
      period: "Aug 2023 - Jun 2023",
      points: [
        "Developed responsive web interfaces using HTML, CSS, Bootstrap and JavaScript",
        "Built REST APIs using Node.js for efficient communication"
      ],
      icon: <FaServer className="text-xl" />
    },
    {
      role: "WEB DEVELOPMENT INTERN",
      company: "MASIA",
      period: "Mar 2023 - July 2023",
      points: [
        "Contributed to development and optimization of web applications",
        "Collaborated on dynamic UI design and responsive web design"
      ],
      icon: <FaMobileAlt className="text-xl" />
    }
  ];

  const skills = [
    { name: "Frontend Development", icon: <FaCode />, description: "React, HTML, CSS, JavaScript" },
    { name: "Backend Development", icon: <FaServer />, description: "Node.js, Express, MongoDB" },
    { name: "UI/UX Design", icon: <FaMobileAlt />, description: "Responsive design, Figma" },
    { name: "Performance Optimization", icon: <FaChartLine />, description: "Page speed, SEO, Analytics" }
  ];

  return (
    <>
    <section id="about" className="py-20 bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800">
      <div className="container mx-auto px-4 max-w-7xl">
        {/* Section Header */}
        <motion.div
          initial={{ opacity: 0, y: 50 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          viewport={{ once: true }}
          className="text-center mb-16"
        >
          <h2 className="text-4xl font-bold mb-2 bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-purple-600">
            About Me
          </h2>
          <p className="text-xl text-gray-600 dark:text-gray-300">
            Get to know me better
          </p>
        </motion.div>

        {/* Content */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-start">
          {/* Image and Skills */}
          <motion.div
            initial={{ opacity: 0, x: -50 }}
            whileInView={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5 }}
            viewport={{ once: true }}
            className="space-y-8"
          >
            {/* Image */}
            <motion.div 
              whileHover={{ scale: 1.02 }}
              className="relative w-full max-w-md mx-auto"
            >
              <div className="relative overflow-hidden rounded-xl shadow-2xl">
                <img 
                  src={aboutImage} 
                  alt="About Shahzaib" 
                  className="w-full h-auto object-cover"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent opacity-0 hover:opacity-100 transition-opacity duration-300 flex items-end p-6">
                  <motion.div
                    initial={{ y: 20 }}
                    whileHover={{ y: 0 }}
                    className="text-white"
                  >
                    <h3 className="text-2xl font-bold">Shahzaib Abbasi</h3>
                    <p className="text-blue-200">Full Stack Developer</p>
                  </motion.div>
                </div>
              </div>
              <div className="absolute -z-10 -inset-4 bg-blue-100 dark:bg-blue-900/20 rounded-xl blur-lg opacity-70"></div>
            </motion.div>

            {/* Skills */}
            <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg">
              <h3 className="text-2xl font-bold text-gray-800 dark:text-white mb-6 flex items-center">
                <FaChartLine className="mr-2 text-blue-500" />
                My Skills
              </h3>
              <div className="grid grid-cols-2 gap-4">
                {skills.map((skill, index) => (
                  <motion.div
                    key={index}
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5, delay: index * 0.1 }}
                    viewport={{ once: true }}
                    whileHover={{ y: -5 }}
                    className="bg-gray-50 dark:bg-gray-700 p-4 rounded-lg flex items-start"
                  >
                    <div className="bg-blue-100 dark:bg-blue-900/30 p-3 rounded-full mr-4 text-blue-600 dark:text-blue-400">
                      {skill.icon}
                    </div>
                    <div>
                      <h4 className="font-bold text-gray-800 dark:text-white">{skill.name}</h4>
                      <p className="text-sm text-gray-600 dark:text-gray-300">{skill.description}</p>
                    </div>
                  </motion.div>
                ))}
              </div>
            </div>
          </motion.div>

          {/* Experience */}
          <motion.div
            initial={{ opacity: 0, x: 50 }}
            whileInView={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5 }}
            viewport={{ once: true }}
            className="space-y-8"
          >
            <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg">
              <h3 className="text-2xl font-bold text-gray-800 dark:text-white mb-4">
                Who am I?
              </h3>
              <p className="text-gray-600 dark:text-gray-300 leading-relaxed mb-4">
                I'm Shahzaib Abbasi, a passionate full-stack developer with expertise in modern web technologies. 
                I specialize in creating high-performance, user-friendly applications with clean code and intuitive interfaces.
              </p>
              <p className="text-gray-600 dark:text-gray-300 leading-relaxed">
                With experience in both frontend and backend development, I bridge the gap between design and technical implementation, 
                delivering solutions that are both visually appealing and technically robust.
              </p>
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg">
              <h3 className="text-2xl font-bold text-gray-800 dark:text-white mb-6 flex items-center">
                <FaCode className="mr-2 text-blue-500" />
                Work Experience
              </h3>
              
              <div className="space-y-8 relative before:absolute before:inset-0 before:ml-5 before:h-full before:w-0.5 before:bg-gradient-to-b from-blue-500 to-purple-500 before:rounded-full">
                {experiences.map((exp, index) => (
                  <motion.div
                    key={index}
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5, delay: index * 0.1 }}
                    viewport={{ once: true }}
                    className="relative pl-10 group"
                  >
                    <div className="absolute left-0 top-1 w-4 h-4 rounded-full bg-blue-500 border-4 border-white dark:border-gray-800 z-10 group-hover:bg-purple-500 transition-colors"></div>
                    
                    <motion.div 
                      whileHover={{ x: 5 }}
                      className="bg-gray-50 dark:bg-gray-700 p-6 rounded-lg shadow-sm hover:shadow-md transition-all"
                    >
                      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-3">
                        <div className="flex items-center">
                          <div className="bg-blue-100 dark:bg-blue-900/30 p-2 rounded-lg mr-4 text-blue-600 dark:text-blue-400">
                            {exp.icon}
                          </div>
                          <h4 className="font-bold text-lg text-gray-800 dark:text-white">
                            {exp.role}
                          </h4>
                        </div>
                        <div className="flex items-center gap-3">
                          <span className="text-sm font-medium bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 px-3 py-1 rounded-full">
                            {exp.company}
                          </span>
                          <span className="text-sm text-gray-500 dark:text-gray-400 whitespace-nowrap">
                            {exp.period}
                          </span>
                        </div>
                      </div>
                      
                      <ul className="space-y-2 pl-2">
                        {exp.points.map((point, i) => (
                          <motion.li 
                            key={i}
                            whileHover={{ x: 5 }}
                            className="flex items-start text-gray-600 dark:text-gray-300"
                          >
                            <span className="mr-2 mt-1 text-blue-500">•</span>
                            {point}
                          </motion.li>
                        ))}
                      </ul>
                    </motion.div>
                  </motion.div>
                ))}
              </div>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
      
      <ReactExpertise theme="dark" />

      <MyJourney theme="dark" /> 



      <WhyMe/> 


      <Connect />



    </>
  );
};

export default About;