import React from 'react';
import { motion } from 'framer-motion';
import { FaLinkedin, FaWhatsapp, FaGithub, FaPhoneAlt } from 'react-icons/fa';
import { HiOutlineMail } from 'react-icons/hi';
import { RiContactsBookLine } from 'react-icons/ri';

const Connect = () => {
  const contacts = [
    {
      name: "Email",
      icon: <HiOutlineMail className="text-2xl" />,
      link: "mailto:your.email@example.com",
      color: "bg-red-500 hover:bg-red-600",
    },
    {
      name: "LinkedIn",
      icon: <FaLinkedin className="text-2xl" />,
      link: "https://linkedin.com/in/your-profile",
      color: "bg-blue-600 hover:bg-blue-700",
    },
    {
      name: "WhatsApp",
      icon: <FaWhatsapp className="text-2xl" />,
      link: "https://wa.me/yournumber",
      color: "bg-green-500 hover:bg-green-600",
    },
    {
      name: "Call",
      icon: <FaPhoneAlt className="text-xl" />,
      link: "tel:+1234567890",
      color: "bg-purple-500 hover:bg-purple-600",
    },
  ];

  return (
    <section className="py-12 px-6 bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-800 dark:to-gray-900">
      <div className="max-w-4xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-12"
        >
          <RiContactsBookLine className="mx-auto text-4xl mb-4 text-indigo-600 dark:text-indigo-400" />
          <h2 className="text-3xl md:text-4xl font-bold text-gray-800 dark:text-white mb-3">
            Let's Connect!
          </h2>
          <p className="text-lg text-gray-600 dark:text-gray-300 max-w-2xl mx-auto">
            Feel free to reach out for collaborations or just a friendly hello.
          </p>
        </motion.div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {contacts.map((contact, index) => (
            <motion.a
              key={index}
              href={contact.link}
              target="_blank"
              rel="noopener noreferrer"
              className={`flex flex-col items-center p-6 rounded-xl shadow-md transition-all duration-300 text-white ${contact.color} hover:shadow-lg`}
              whileHover={{ y: -5 }}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
            >
              <div className="mb-3">{contact.icon}</div>
              <h3 className="text-xl font-semibold">{contact.name}</h3>
              <p className="text-sm opacity-80 mt-1">Click to connect</p>
            </motion.a>
          ))}
        </div>

        {/* Additional Contact Button */}
        <motion.div
          className="mt-12 text-center"
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ delay: 0.4 }}
        >
          <a
            href="/contact" // Link to your contact page
            className="inline-flex items-center px-8 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-full transition-all shadow-lg hover:shadow-xl"
          >
            <span>Contact Form</span>
            <svg
              xmlns="http://www.w3.org/2000/svg"
              className="h-5 w-5 ml-2"
              viewBox="0 0 20 20"
              fill="currentColor"
            >
              <path
                fillRule="evenodd"
                d="M10.293 5.293a1 1 0 011.414 0l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414-1.414L12.586 11H5a1 1 0 110-2h7.586l-2.293-2.293a1 1 0 010-1.414z"
                clipRule="evenodd"
              />
            </svg>
          </a>
        </motion.div>
      </div>
    </section>
  );
};

export default Connect;