// src/components/ReactExpertise.jsx
import { motion } from 'framer-motion';
import { FiCode, FiCpu, FiLayers, FiZap } from 'react-icons/fi';

const ReactExpertise = ({ theme }) => {
  const expertise = [
    {
      icon: <FiCode />,
      title: "React Hooks Expert",
      description: "Clean, efficient component logic with custom hooks",
      color: "text-indigo-500",
      darkColor: "text-indigo-400",
      tags: ["useState", "useEffect", "Custom Hooks"]
    },
    {
      icon: <FiCpu />,
      title: "State Management",
      description: "Context API, Redux, and Zustand solutions",
      color: "text-blue-500",
      darkColor: "text-blue-400",
      tags: ["Redux Toolkit", "Context API", "Zustand"]
    },
    {
      icon: <FiLayers />,
      title: "Reusable UI Patterns",
      description: "Component libraries & design systems",
      color: "text-purple-500",
      darkColor: "text-purple-400",
      tags: ["Storybook", "Atomic Design", "UI Kits"]
    },
    {
      icon: <FiZap />,
      title: "Performance Optimization",
      description: "Memoization, code splitting, lazy loading",
      color: "text-teal-500",
      darkColor: "text-teal-400",
      tags: ["React.memo", "useMemo", "Suspense"]
    }
  ];

  const container = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const item = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: {
        duration: 0.5,
        ease: "easeOut"
      }
    }
  };

  return (
    <section className={`py-12 sm:py-16 lg:py-20 ${theme === 'dark' ? 'bg-gray-900' : 'bg-gray-50'}`} id="react-expertise">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-10 sm:mb-12 lg:mb-16"
        >
          <h2 className={`text-2xl sm:text-3xl lg:text-4xl font-bold mb-3 sm:mb-4 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
            React Development Expertise
          </h2>
          <div className={`w-16 sm:w-20 h-1 mx-auto mb-4 sm:mb-6 ${theme === 'dark' ? 'bg-indigo-500' : 'bg-indigo-600'}`}></div>
          <p className={`text-base sm:text-lg max-w-2xl mx-auto ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
            Specialized skills that elevate your React projects
          </p>
        </motion.div>

        <motion.div
          variants={container}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-50px" }}
          className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5 sm:gap-6 lg:gap-8"
        >
          {expertise.map((skill, index) => (
            <motion.div
              key={index}
              variants={item}
              whileHover={{ y: -5, scale: 1.02 }}
              className={`flex flex-col items-center text-center p-5 sm:p-6 rounded-lg ${
                theme === 'dark' ? 'bg-gray-800 hover:bg-gray-750' : 'bg-white hover:bg-gray-50'
              } shadow-md transition-all duration-300 border ${
                theme === 'dark' ? 'border-gray-700' : 'border-gray-200'
              }`}
            >
              <div className={`mb-3 sm:mb-4 text-2xl sm:text-3xl ${theme === 'dark' ? skill.darkColor : skill.color}`}>
                {skill.icon}
              </div>
              <h3 className={`text-lg sm:text-xl font-bold mb-2 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
                {skill.title}
              </h3>
              <p className={`text-sm sm:text-base mb-3 ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
                {skill.description}
              </p>
              <div className="flex flex-wrap justify-center gap-2 mt-2">
                {skill.tags.map((tag, i) => (
                  <span
                    key={i}
                    className={`text-xs px-2 py-1 rounded-full ${
                      theme === 'dark' ? 'bg-gray-700 text-gray-200' : 'bg-gray-100 text-gray-800'
                    }`}
                  >
                    {tag}
                  </span>
                ))}
              </div>
            </motion.div>
          ))}
        </motion.div>
      </div>
    </section>
  );
};

export default ReactExpertise;