// src/components/MyJourney.jsx
import { motion } from 'framer-motion';
import { FiBriefcase, FiBook, FiCode, FiAward } from 'react-icons/fi';

const MyJourney = ({ theme }) => {
  const milestones = [
    {
      id: 1,
      year: "2023 – Present",
      title: "Full Stack Developer @ QuantumStack",
      description: "Building scalable web applications with React, Node.js, and AWS",
      icon: <FiBriefcase />,
      type: "work",
      tags: ["React", "Node.js", "AWS"]
    },
    {
      id: 2,
      year: "2022 – 2023",
      title: "React Intern @ 92Devis",
      description: "Developed UI components and optimized frontend performance",
      icon: <FiCode />,
      type: "work",
      tags: ["React", "Redux", "Performance"]
    },
    {
      id: 3,
      year: "2021 – 2022",
      title: "MERN Stack Certification",
      description: "Completed 500+ hours of hands-on coding projects",
      icon: <FiBook />,
      type: "education",
      tags: ["MongoDB", "Express", "React", "Node.js"]
    },
    {
      id: 4,
      year: "2020 – 2021",
      title: "Computer Science Degree",
      description: "Graduated with honors from Tech University",
      icon: <FiAward />,
      type: "education",
      tags: ["Algorithms", "Data Structures", "CS Fundamentals"]
    }
  ];

  const container = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.15
      }
    }
  };

  const item = {
    hidden: { y: 30, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: {
        duration: 0.6,
        ease: "easeOut"
      }
    }
  };

  return (
    <section className={`py-16 md:py-20 ${theme === 'dark' ? 'bg-gray-900' : 'bg-gray-50'}`} id="journey">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-12 md:mb-16"
        >
          <h2 className={`text-3xl md:text-4xl font-bold mb-3 md:mb-4 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
            My Journey
          </h2>
          <div className={`w-16 md:w-20 h-1 mx-auto mb-4 md:mb-6 ${theme === 'dark' ? 'bg-indigo-500' : 'bg-indigo-600'}`}></div>
          <p className={`text-base md:text-lg max-w-2xl mx-auto ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
            Education and professional milestones that shaped my career
          </p>
        </motion.div>

        <motion.div
          variants={container}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-50px" }}
          className="relative"
        >
          {/* Vertical line */}
          <div className={`absolute left-6 sm:left-8 md:left-1/2 h-full w-0.5 md:w-1 transform -translate-x-1/2 ${theme === 'dark' ? 'bg-gray-700' : 'bg-gray-200'}`}></div>

          <div className="space-y-8 sm:space-y-12">
            {milestones.map((milestone, index) => (
              <motion.div
                key={milestone.id}
                variants={item}
                className="relative"
                whileHover={{ scale: 1.02 }}
              >
                {/* Dot with pulse animation */}
                <motion.div
                  className={`absolute top-6 left-6 sm:left-8 md:left-1/2 w-3 h-3 sm:w-4 sm:h-4 rounded-full transform -translate-x-1/2 -translate-y-1/2 z-10 ${
                    milestone.type === "work" 
                      ? theme === 'dark' ? 'bg-blue-500' : 'bg-blue-600'
                      : theme === 'dark' ? 'bg-purple-500' : 'bg-purple-600'
                  }`}
                  animate={{
                    scale: [1, 1.2, 1],
                    opacity: [0.8, 1, 0.8]
                  }}
                  transition={{
                    duration: 2,
                    repeat: Infinity,
                    ease: "easeInOut"
                  }}
                />

                {/* Card */}
                <div className={`ml-12 sm:ml-16 md:ml-0 md:w-[calc(50%-20px)] p-5 sm:p-6 rounded-lg shadow-md ${
                  index % 2 === 0 
                    ? 'md:mr-auto md:pr-8 md:pl-4' 
                    : 'md:ml-auto md:pl-8 md:pr-4'
                } ${theme === 'dark' ? 'bg-gray-800 hover:bg-gray-750' : 'bg-white hover:bg-gray-50'} transition-colors duration-300 border ${
                  theme === 'dark' ? 'border-gray-700' : 'border-gray-200'
                }`}
                >
                  <div className={`flex items-center mb-2 ${
                    milestone.type === "work" 
                      ? theme === 'dark' ? 'text-blue-400' : 'text-blue-600'
                      : theme === 'dark' ? 'text-purple-400' : 'text-purple-600'
                  }`}>
                    <span className="mr-2 text-lg">{milestone.icon}</span>
                    <span className="font-medium text-sm sm:text-base">{milestone.year}</span>
                  </div>
                  <h3 className={`text-lg sm:text-xl font-bold mb-2 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
                    {milestone.title}
                  </h3>
                  <p className={`text-sm sm:text-base mb-3 ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
                    {milestone.description}
                  </p>
                  
                  {/* Tags */}
                  <div className="flex flex-wrap gap-2 mt-3">
                    {milestone.tags.map((tag, i) => (
                      <span
                        key={i}
                        className={`text-xs sm:text-sm px-2 py-1 rounded-full ${
                          milestone.type === "work"
                            ? theme === 'dark' 
                              ? 'bg-blue-900/30 text-blue-300'
                              : 'bg-blue-100 text-blue-800'
                            : theme === 'dark'
                              ? 'bg-purple-900/30 text-purple-300'
                              : 'bg-purple-100 text-purple-800'
                        }`}
                      >
                        {tag}
                      </span>
                    ))}
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </motion.div>
      </div>
    </section>
  );
};

export default MyJourney;